<#
    HIT MUSIC - ATUALIZACOES FINAIS (INSTALADOR DIRETO)
    ===================================================

    Grava os arquivos ja atualizados na pasta do jogo. NAO usa git, nao
    depende da versao em que a pasta esta e nao precisa da pasta limpa:
    cada arquivo trocado e copiado antes para uma pasta de backup.

    O que entra:

      1. VOLTAR na tela de escolha do modo (dificuldade), no mesmo desenho
         do painel. O cursor anda por FACIL / DIFICIL / VOLTAR pelos tres
         botoes que ja ficam acesos (A sobe, E desce, B confirma).

      2. Configuracoes (F9 / SELECT) acendendo A, E e B na mesa: a serial
         da tela anterior e cancelada (CLEAR) e o quadro do menu sobe em
         seguida, sem herdar o ATTRACT da abertura.

      3. Botao IMPORTAR TODAS na tela de musicas: importa o pendrive
         inteiro, avisa quais pacotes nao estao funcionando e conta os
         que ja tinham entrado, para refazer sem repetir trabalho.

      4. QUIOSQUE DA MOLDURA TOUCH: nada do Windows por cima do jogo -
         marca cinza do dedo, notificacoes, teclado virtual, janela do
         pendrive, protetor de tela, arrastar da borda.

      5. NOME COMPRIDO DE MUSICA que se vira sozinho: encolhe, quebra em
         duas linhas e, no limite, corta com reticencias - sem estourar
         card, painel nem HUD.

      6. PONTEIRO DO MOUSE some do jogo inteiro (a cena da musica pedia
         ele de volta, por isso a seta so aparecia durante a partida).

      7. ARRASTO so vale no toque: apertar a lane de partida e a de
         chegada nao conta mais o ponto, e o arrasto nao acende LED
         nenhum. So conclui quem realmente varre o caminho com o dedo.

    COMO RODAR (PowerShell, dentro da pasta do jogo):

        powershell -ExecutionPolicy Bypass -File .\instalar_atualizacoes_finais.ps1

    Conferir depois, sem abrir o gabinete:

        godot --headless --path . res://tools/smoke_final.tscn

    Desfazer: os originais ficam em _backup_hit_music_<data>_<hora>\ .
    Rodar duas vezes nao faz mal: o script avisa que o arquivo ja esta
    atualizado e nao mexe nele.
#>

param(
    [string]$Repo = "."
)

$ErrorActionPreference = "Stop"

function Passo($texto) { Write-Host "`n==> $texto" -ForegroundColor Cyan }
function Ok($texto)    { Write-Host "    OK     $texto" -ForegroundColor Green }
function Aviso($texto) { Write-Host "    !      $texto" -ForegroundColor Yellow }
function Info($texto)  { Write-Host "           $texto" -ForegroundColor DarkGray }

function Parar($texto) {
    Write-Host ""
    Write-Host "ERRO: $texto" -ForegroundColor Red
    exit 1
}

function Sha256Arquivo($caminho) {
    $sha = [System.Security.Cryptography.SHA256]::Create()
    try {
        $bytes = [System.IO.File]::ReadAllBytes($caminho)
        return ([BitConverter]::ToString($sha.ComputeHash($bytes)) -replace "-", "")
    } finally {
        $sha.Dispose()
    }
}

$script:Backup = ""
$script:Raiz = ""

## Guarda o original antes de qualquer escrita, mantendo a arvore de
## pastas: para voltar atras basta copiar o backup por cima.
function Guardar-Original($caminhoRelativo) {
    $origem = Join-Path $script:Raiz ($caminhoRelativo -replace "/", "\")
    if (-not (Test-Path -LiteralPath $origem)) { return }

    $alvo = Join-Path $script:Backup ($caminhoRelativo -replace "/", "\")
    $pasta = Split-Path -Parent $alvo
    if (-not (Test-Path -LiteralPath $pasta)) {
        New-Item -ItemType Directory -Path $pasta -Force | Out-Null
    }
    Copy-Item -LiteralPath $origem -Destination $alvo -Force
}

Passo "Conferindo a pasta do jogo"

if (-not (Test-Path -LiteralPath $Repo)) { Parar "Pasta nao encontrada: $Repo" }
$script:Raiz = (Resolve-Path -LiteralPath $Repo).Path

if (-not (Test-Path -LiteralPath (Join-Path $script:Raiz "project.godot"))) {
    Parar "Nao achei project.godot em $($script:Raiz). Rode o script na raiz do projeto Hit Music."
}
Ok "projeto Hit Music em $($script:Raiz)"

$carimbo = Get-Date -Format "yyyy-MM-dd_HH-mm-ss"
$script:Backup = Join-Path $script:Raiz ("_backup_hit_music_" + $carimbo)

$arquivos = @()

