Passo "Gravando os arquivos"

$trocados = 0
$iguais = 0
$divergentes = @()

foreach ($item in $arquivos) {
    $destino = Join-Path $script:Raiz ($item.Caminho -replace "/", "\")
    $pasta = Split-Path -Parent $destino

    $atual = ""
    if (Test-Path -LiteralPath $destino) {
        $atual = Sha256Arquivo $destino
    }

    if ($atual -eq $item.HashNovo) {
        Ok ("ja atualizado    " + $item.Caminho)
        $iguais++
        continue
    }

    if ($atual -ne "") { Guardar-Original $item.Caminho }

    if (-not (Test-Path -LiteralPath $pasta)) {
        New-Item -ItemType Directory -Path $pasta -Force | Out-Null
    }

    $bytes = [Convert]::FromBase64String(($item.Base64 -replace "\s", ""))
    [System.IO.File]::WriteAllBytes($destino, $bytes)

    if ((Sha256Arquivo $destino) -ne $item.HashNovo) {
        Parar ("O arquivo " + $item.Caminho + " nao gravou corretamente.")
    }

    if ($atual -eq "") {
        Ok ("novo             " + $item.Caminho)
    } elseif ($item.HashBeta -ne "" -and $atual -ne $item.HashBeta) {
        # A pasta tinha uma versao diferente da Beta 12 (edicao local ou
        # outra build). O arquivo entra atualizado, mas fica o aviso e o
        # backup para o operador comparar o que era dele.
        Aviso ("substituido*     " + $item.Caminho)
        $divergentes += $item.Caminho
    } else {
        Ok ("atualizado       " + $item.Caminho)
    }
    $trocados++
}

# ---------------------------------------------------------------
# project.godot e export_presets.cfg NAO sao substituidos: eles guardam
# ajustes da maquina do operador (caminho de export, resolucao, teclas).
# Aqui so entram as linhas novas.
# ---------------------------------------------------------------

Passo "Ajustando project.godot (janela sempre no topo)"

$caminhoProjeto = Join-Path $script:Raiz "project.godot"
$projeto = [System.IO.File]::ReadAllText($caminhoProjeto)

if ($projeto -match "window/size/always_on_top\s*=\s*true") {
    Ok "janela ja nasce no topo"
} else {
    Guardar-Original "project.godot"

    $blocoNovo = @'
; Tela cheia EXCLUSIVA, sem borda e sempre no topo desde o primeiro
; quadro. O ArcadeShell reafirma isso a cada 0,35 s, mas comecar assim
; fecha a fresta em que uma notificacao do Windows ainda alcancava a
; janela durante a abertura.
window/size/mode=4
window/size/borderless=true
window/size/always_on_top=true
'@ -replace "`r`n", "`n"

    if ($projeto -match "(?m)^window/size/mode=\d+\s*$") {
        $projeto = [regex]::Replace(
            $projeto, "(?m)^window/size/mode=\d+[ \t]*\r?\n", $blocoNovo)
        Ok "tela cheia exclusiva + sem borda + sempre no topo"
    } elseif ($projeto -match "(?m)^\[display\]") {
        $projeto = [regex]::Replace(
            $projeto, "(?m)^\[display\][ \t]*\r?\n", "[display]`n`n" + $blocoNovo, 1)
        Ok "secao [display] ajustada"
    } else {
        $projeto = $projeto.TrimEnd() + "`n`n[display]`n`n" + $blocoNovo
        Ok "secao [display] criada"
    }

    [System.IO.File]::WriteAllText(
        $caminhoProjeto, $projeto, (New-Object System.Text.UTF8Encoding($false)))
}

Passo "Ajustando export_presets.cfg (o .ps1 do quiosque no executavel)"

$caminhoExport = Join-Path $script:Raiz "export_presets.cfg"
if (-not (Test-Path -LiteralPath $caminhoExport)) {
    Aviso "export_presets.cfg nao existe nesta pasta - nada a fazer"
} else {
    $export = [System.IO.File]::ReadAllText($caminhoExport)

    if ($export -match "QUIOSQUE_HIT_MUSIC\.ps1") {
        Ok "o quiosque ja entra no executavel"
    } elseif ($export -match 'include_filter="([^"]*)"') {
        Guardar-Original "export_presets.cfg"
        $atualFiltro = $Matches[1]
        $novoFiltro = if ([string]::IsNullOrWhiteSpace($atualFiltro)) {
            "QUIOSQUE_HIT_MUSIC.ps1"
        } else {
            $atualFiltro + ",QUIOSQUE_HIT_MUSIC.ps1"
        }
        $regexFiltro = [regex]::new('include_filter="[^"]*"')
        $export = $regexFiltro.Replace($export, ('include_filter="' + $novoFiltro + '"'), 1)
        [System.IO.File]::WriteAllText(
            $caminhoExport, $export, (New-Object System.Text.UTF8Encoding($false)))
        Ok ("include_filter agora e: " + $novoFiltro)
    } else {
        Aviso "nao achei include_filter - adicione QUIOSQUE_HIT_MUSIC.ps1 a mao ao exportar"
    }
}

Write-Host ""
Write-Host ("Arquivos gravados: " + $trocados + "   ja atualizados: " + $iguais) -ForegroundColor Green

if (Test-Path -LiteralPath $script:Backup) {
    Info ("originais guardados em " + $script:Backup)
}

if ($divergentes.Count -gt 0) {
    Write-Host ""
    Aviso "Estes arquivos NAO estavam iguais aos da Beta 12 - se voce tinha mexido neles,"
    Aviso "compare com a copia do backup antes de seguir:"
    foreach ($nome in $divergentes) { Info ("  " + $nome) }
}

